#!/usr/bin/env bash
# Regenerates every launcher icon from the design in assets/icon/app_icon.svg
# (which embeds the department logo assets/images/dept_logo.png):
#   * Android adaptive icon (foreground + gradient background, API 26+) and
#     the legacy mipmaps;
#   * iOS AppIcon set (opaque — the App Store rejects transparency);
#   * web favicon and PWA icons (normal + maskable).
# Needs headless Chromium (SVG filters, Arabic text in Cairo) and ImageMagick,
# both present in the Claude Code cloud container. Re-run after changing the
# design, then commit the generated files. Preview: build/icon_preview.png.
set -euo pipefail
cd "$(dirname "$0")/.."

CHROME="${CHROME:-$(ls -d /opt/pw-browsers/chromium_headless_shell-*/chrome-linux/headless_shell 2>/dev/null | tail -1)}"
[[ -x "$CHROME" ]] || { echo "headless Chromium not found (set CHROME=...)"; exit 1; }
command -v convert >/dev/null || { echo "ImageMagick (convert) not found"; exit 1; }

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
root="$PWD"
bg_color='#FFFFFF' # the design's background (white, no dark frame)

# render NAME VIEWBOX CSS — the design at 1024×1024 with CSS tweaks.
render() {
  {
    cat <<EOF
<!doctype html><meta charset="utf-8"><style>
@font-face{font-family:Cairo;src:url('file://$root/assets/fonts/cairo/Cairo-Bold.ttf');font-weight:100 900}
html,body{margin:0;background:transparent}
svg{display:block;width:1024px;height:1024px}
$3
</style>
EOF
    sed -e "s#href=\"dept_logo.png\"#href=\"file://$root/assets/images/dept_logo.png\"#g" \
        -e "s#viewBox=\"0 0 512 512\"#viewBox=\"$2\"#" assets/icon/app_icon.svg
  } >"$tmp/$1.html"
  "$CHROME" --no-sandbox --headless --hide-scrollbars --allow-file-access-from-files \
    --default-background-color=00000000 --window-size=1024,1024 \
    --screenshot="$tmp/$1.png" "file://$tmp/$1.html" >/dev/null 2>&1
}

full_bleed='svg>rect:nth-of-type(1){x:0;y:0;width:512px;height:512px;rx:0}svg>rect:nth-of-type(2){display:none}'
render rounded '0 0 512 512' ''                                     # the design as drawn
render full '0 0 512 512' "$full_bleed"                              # square, OS applies its mask
render background '0 0 512 512' "$full_bleed svg>g{display:none}"    # gradient only
# Adaptive foreground: on the white background only the clipboard's
# contents matter (title, rows, logo, clip — within a 200-unit radius of
# (256,240)), so they are framed to fit the launcher's safe circle (66 of
# the 108 dp layer) and the paper's edges may fall outside it.
render foreground '-74 -90 660 660' 'svg>rect{display:none}'

opaque() { convert "$1" -background "$bg_color" -alpha remove -alpha off "$2"; }

# ---------------------------------------------------------------- Android --
res=android/app/src/main/res
for d in mdpi:48:108 hdpi:72:162 xhdpi:96:216 xxhdpi:144:324 xxxhdpi:192:432; do
  IFS=: read -r density legacy layer <<<"$d"
  mkdir -p "$res/mipmap-$density"
  convert "$tmp/rounded.png" -resize "${legacy}x${legacy}" "$res/mipmap-$density/ic_launcher.png"
  convert "$tmp/foreground.png" -resize "${layer}x${layer}" "$res/mipmap-$density/ic_launcher_foreground.png"
  opaque "$tmp/background.png" "$tmp/bg_opaque.png"
  convert "$tmp/bg_opaque.png" -resize "${layer}x${layer}" "$res/mipmap-$density/ic_launcher_background.png"
done
mkdir -p "$res/mipmap-anydpi-v26"
cat >"$res/mipmap-anydpi-v26/ic_launcher.xml" <<'EOF'
<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by tool/build_icons.sh -->
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@mipmap/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
EOF

# -------------------------------------------------------------------- iOS --
ios=ios/Runner/Assets.xcassets/AppIcon.appiconset
opaque "$tmp/full.png" "$tmp/full_opaque.png"
for f in "$ios"/Icon-App-*.png; do
  name="$(basename "$f" .png)"                     # Icon-App-83.5x83.5@2x
  points="${name#Icon-App-}"; points="${points%%x*}"
  scale="${name##*@}"; scale="${scale%x}"
  px="$(awk "BEGIN{printf \"%d\", $points*$scale + 0.5}")"
  convert "$tmp/full_opaque.png" -resize "${px}x${px}" "$f"
done

# -------------------------------------------------------------------- web --
convert "$tmp/rounded.png" -resize 192x192 web/icons/Icon-192.png
convert "$tmp/rounded.png" -resize 512x512 web/icons/Icon-512.png
convert "$tmp/bg_opaque.png" "$tmp/foreground.png" -composite "$tmp/maskable.png"
convert "$tmp/maskable.png" -resize 192x192 web/icons/Icon-maskable-192.png
convert "$tmp/maskable.png" -resize 512x512 web/icons/Icon-maskable-512.png
convert "$tmp/rounded.png" -resize 32x32 web/favicon.png

# ---------------------------------------------------------------- preview --
# Design | Android circle | Android squircle | iOS | real size.
mkdir -p build
convert -size 1024x1024 xc:none -fill white -draw 'circle 512,512 512,0' "$tmp/m_circle.png"
convert -size 1024x1024 xc:none -fill white -draw 'roundrectangle 0,0 1023,1023 300,300' "$tmp/m_squircle.png"
convert -size 1024x1024 xc:none -fill white -draw 'roundrectangle 0,0 1023,1023 230,230' "$tmp/m_ios.png"
# The launcher shows the middle 72/108 of the adaptive layers.
convert "$tmp/maskable.png" -gravity center -crop 683x683+0+0 +repage -resize 1024x1024 "$tmp/adaptive.png"
convert "$tmp/adaptive.png" "$tmp/m_circle.png" -alpha set -compose DstIn -composite "$tmp/p_circle.png"
convert "$tmp/adaptive.png" "$tmp/m_squircle.png" -alpha set -compose DstIn -composite "$tmp/p_squircle.png"
convert "$tmp/full_opaque.png" "$tmp/m_ios.png" -alpha set -compose DstIn -composite "$tmp/p_ios.png"
# Last tile: actual size on a typical (xxhdpi) home screen, 48dp = 144 px.
convert "$tmp/p_squircle.png" -resize 144x144 "$tmp/p_small.png"
convert \( "$tmp/rounded.png" "$tmp/p_circle.png" "$tmp/p_squircle.png" "$tmp/p_ios.png" -resize 300x300 \) \
  "$tmp/p_small.png" -background '#ECEFF1' -gravity center -extent 340x340 +append build/icon_preview.png

echo "Icons regenerated. Preview: build/icon_preview.png"
